       hatchGlide schedules) — the canvas rides ordergrp's scale like the ref
       div does, so NO live-scale conversion is applied here. An earlier /osc
       "fix" inflated the pattern 1/osc× and shifted the whole E-segment chain
       +43 screen px (f290-310 measured) — do not reintroduce it. */
    if (T >= 7.3 && T <= 11.3) {
      if (hf <= 229) Xo = 0;
      else if (hf <= 263) Xo = 10 * (hf - 229) + 210 * (1 - Math.exp(-(hf - 229) / 7));
      else if (hf < 285) Xo = 548.4;
      else { var hu = Math.min(hf - 285, 97.8); Xo = 548.4 + (4.4 * hu - 0.0225 * hu * hu) / 0.493; }
    }
    var HDX = Math.sin(132 * Math.PI / 180), HDY = -Math.cos(132 * Math.PI / 180);
    var drawBH = function (cv, W, H, X, col, P, ph, ph2, segX) {
      if (!cv) return;
      cv.clear();
      var Dw = W + 62, Dh = H + 62; /* div box: padding-box origin inset(-30) */
      var HL = Dw * HDX + Dh * (-HDY);
      var sx = W / 2 - (HL / 2) * HDX, sy = H / 2 - (HL / 2) * HDY;
      var hp = new CK.Paint(); hp.setStyle(CK.PaintStyle.Stroke); hp.setStrokeWidth(1.5);
      hp.setColor(CK.Color(col[0], col[1], col[2], col[3]));
      var hnx = -HDY, hny = HDX, hhalf = W + H;
      var hs0 = 0.75;
      var hkMin = Math.floor((-hs0 - hhalf) / P), hkMax = Math.ceil(hhalf / P) + 2;
      /* ref o-box shows a phase discontinuity at pattern-x ≈ 4.6 (screen 458.6
         at X=0, measured f240/f250/f270 y405): LEFT of it the chain runs at
         ph2 (= main −102.9), RIGHT at ph. Vertical boundary glides with X. */
      var segs = (ph2 === undefined) ? [[1, 1, W - 1, H - 1, ph]]
                                     : [[1, 1, segX + X, H - 1, ph2], [segX + X, 1, W - 1, H - 1, ph]];
      for (var si = 0; si < segs.length; si++) {
        cv.save(); cv.clipRect(segs[si].slice(0, 4));
        for (var hk = hkMin; hk <= hkMax; hk++) {
          var hs = hs0 + hk * P;
          var hax = sx + hs * HDX + X + segs[si][4], hay = sy + hs * HDY;
          cv.drawLine(hax - hnx * hhalf, hay - hny * hhalf, hax + hnx * hhalf, hay + hny * hhalf, hp);
        }
        cv.restore();
      }
    };
    /* ours single-chain phase tracked ref LEFT segment at −2px (f240 −2.5, f270 −1.7):
       left seg ph2 = −16.5, right seg (A chain) = ours + 104.9 = 86.4.
       Segment boundary: bracketing reads give screen-boundary = box-left + X_screen
       with residual 0±15 in BOTH D (f240 ∈(683.5,786.5), f270 ∈(955.5,1059)) and E
       (f290 ∈(984,1035), f310 ∈(1059,1110)) → boundary local = Xo, constant 0. */
    drawBH(OC, 1010, 379, Xo, [48, 48, 48, oHA], 119.6, 88.4, -14.5, 0);
    /* m/a-box hatch (ported r16; r15 rollback cause "canvas as flex item" was
       probe-refuted this round: absolute class IS honored on , text
       centering identical with/without it — zz-canvasabs probe). Structure
       measured from ref f290/f300/f310/f320/f330/f340 (scanline.py/extr.py):
       - main chain: repeating-linear-gradient(132deg,#252525 0 1.5px,transp 1.5px
         65.4px) → slope dx/dy = -0.9004, horizontal pitch 88.0. Glide = hatchGlide
         Xm/Xa (index.html:1140-1146); anchors cross-validated on 3 frames each
         (m: x(y455) = 58.6+Xm mod 88, f290/300/330 err ≤2px; a: 44.9+Xa, same).
       - m-box extra chain = main −50px: ABSENT f290, two 30px stubs f300,
         near-full f310-330, gone with the box at DE exit (f339+). a-box NEVER
         shows it. Chrome tile artifact, not in source CSS — drawn full here
         (mid-transition cost ≈ half a chain ≈ 0.02%/frame, negligible). */
    if (T >= 9.1 && T <= 11.3) {
      var mHC = ctx.getCanvasById('mhatch-canvas'), aHC = ctx.getCanvasById('ahatch-canvas');
      var Xm2 = 0, Xa2 = 0;
      if (hf >= 285) { var mu2 = Math.min(hf - 285, 97.8); Xm2 = 4.4 * mu2 - 0.0225 * mu2 * mu2; }
      if (hf >= 286) {
        if (hf <= 299) Xa2 = -36 * (1 - Math.exp(-(hf - 286) / 6));
        else { var au2 = Math.min(hf - 300, 95); Xa2 = -31.88 + 1.9 * au2 - 0.01 * au2 * au2; }
      }
      var drawMA = function (cv, boxL, anchor, X, chains) {
        if (!cv) return;
        cv.clear();
        var hp2 = new CK.Paint(); hp2.setStyle(CK.PaintStyle.Stroke); hp2.setStrokeWidth(1.5);
        hp2.setColor(CK.Color(37, 37, 37, 1));
        var slope = -0.9004, pitch = 88.0, y0 = 18, yTop = -200, yBot = 400;
        for (var ci = 0; ci < chains.length; ci++) {
          var x0 = anchor + X + chains[ci] - boxL;
          /* line hits the box if xs + slope*(y-18) ∈ [0,520] for some y∈[0,183]
             → xs ∈ [-345, 684]; pad and enumerate k around that window. */
          var k0 = Math.floor((-350 - x0) / pitch) - 1, k1 = Math.ceil((690 - x0) / pitch) + 1;
          for (var k = k0; k <= k1; k++) {
            var xs = x0 + k * pitch;
            cv.drawLine(xs + slope * (yTop - y0), yTop, xs + slope * (yBot - y0), yBot, hp2);
          }
        }
      };
      drawMA(mHC, 130, 58.6, Xm2, [0]);
      drawMA(aHC, 1260, 44.9, Xa2, [0]);
    }
  }
  // D→E morph: order box shrinks (9.103 → 9.653)
  if (T>= 9.103 && T < 9.703) {
    var mW = clamp((T - 9.103) / 0.55, 0, 1);
    mW = 1 - Math.pow(1 - mW, 4); /* ref ease "power3.out": GSAP Power3 = QUART (naming off-by-one), 1-(1-q)^4 */
    ctx.getNode('ordergrp').scale(1 + (0.493 - 1) * mW);
    ctx.getNode('ordergrp').translateX(4 * mW); ctx.getNode('ordergrp').translateY(-11 * mW);
  } else if (T>= 9.703) {
    ctx.getNode('ordergrp').scale(0.493); ctx.getNode('ordergrp').translateX(4); ctx.getNode('ordergrp').translateY(-11);
  }
  // flanking boxes fly in from offscreen
  [['mktgrp', 9.133, -700, 600], ['astgrp', 9.18, 700, 600]].forEach(function (b) {
    if (T < b[1]) { ctx.getNode(b[0]).opacity(0); }
    else if (T < b[1] + 0.55) {
      var bw = clamp((T - b[1]) / 0.55, 0, 1);
      bw = 1 - Math.pow(1 - bw, 4); /* ref ease "power3.out": GSAP Power3 = QUART, 1-(1-q)^4 (f278 probe: y 725.5/s 1.525 exact) */
      ctx.getNode(b[0]).opacity(bw); /* ref tweens autoAlpha 0→1 in the SAME tween: opacity follows the ease */
      ctx.getNode(b[0]).translateX(b[2] * (1 - bw)); ctx.getNode(b[0]).translateY(b[3] * (1 - bw));
      ctx.getNode(b[0]).scale(2.6 + (1 - 2.6) * bw);
    } else { ctx.getNode(b[0]).opacity(1); ctx.getNode(b[0]).translateX(0); ctx.getNode(b[0]).translateY(0); ctx.getNode(b[0]).scale(1); }
  });
  // three drop-lines rise (10.653 + i*0.09), ease power2.out
  // (index.html:1708 `tl.to(id,{autoAlpha:0.9, scaleY:1, duration:0.3, ease:"power2.out"})`)
  ['dl1', 'dl2', 'dl3'].forEach(function (id, i) {
    var dlStart = 10.653 + i * 0.09;
    if (T < dlStart) { ctx.getNode(id).opacity(0); ctx.getNode(id).scaleY(0); }
    else if (T < dlStart + 0.3) {
      var dlQ = clamp((T - dlStart) / 0.3, 0, 1);
      var dw = 1 - Math.pow(1 - dlQ, 3); /* GSAP power2.out = 1-(1-q)^3 */
      ctx.getNode(id).opacity(0.9 * dw); ctx.getNode(id).scaleY(dw);
    }
    else { ctx.getNode(id).opacity(0.9); ctx.getNode(id).scaleY(1); }
  });
