    ctx.getNode('sceneDE').opacity(1 - eFadeW * eFadeW);
  }
}

/* ════════════ SCENE F+G: brace card (11.233 → 13.7s) ═════════════ */
var FG_ON = (T>= 11.233 && T < 13.7);
vis('sceneFG', FG_ON);
if (FG_ON) {
